sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float strength;
uniform float blockSize;
uniform float2 stretch;
uniform float seed;
uniform float fade;
uniform float2 offset;
float hash12(float2 p) {
    float3 q = fract(float3(p.xyx) * 0.1031);
    q += dot(q, q.yzx + 33.33);
    return fract((q.x + q.y) * q.z);
}
float2 hash22(float2 p) {
    float3 q = fract(float3(p.xyx) * float3(0.1031, 0.1030, 0.0973));
    q += dot(q, q.yzx + 33.33);
    return fract((q.xx + q.yz) * q.zy);
}
half4 main(float2 coord) {
    float2 dims = max(abs(stretch), float2(0.01)) * max(blockSize, 1.0);
    float h = hash12(floor((coord - size * 0.5 - offset) / dims) + seed * 11.7);
    float m = strength * (1.0 + 2.0 * fade) - fade;
    float keep = fade > 0.0 ? smoothstep(m - fade, m + fade, h) : step(strength, h);
    return image.eval(coord) * half(keep);
}
